settings.custom_css:
/* حذف کامل بکگراند عکس */
.elementor-widget-image,
.elementor-widget-image .elementor-widget-container,
.elementor-widget-image img {
    background: transparent !important;
    background-color: transparent !important;
}

/* اطمینان از شفاف بودن خود تصویر */
.elementor-widget-image img {
    mix-blend-mode: normal !important;
}

/* =========================================================
   NUMBER ICON
   کلاس: number-icon
   ========================================================= */

.number-icon {
    width: 58px !important;
    min-width: 58px !important;
    height: 58px !important;
    min-height: 58px !important;

    display: flex !important;
    align-items: center !important;
    justify-content: center !important;

    background: linear-gradient(135deg, #006660, #004d4d) !important;
    border: 2px solid #FFCE3A !important;
    border-radius: 18px !important;

    box-shadow: 0 10px 25px rgba(0, 102, 96, 0.22) !important;

    position: relative;
    overflow: hidden;

    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease !important;
}


/* عدد داخل آیکون */
.number-icon p {
    margin: 0 !important;
    padding: 0 !important;

    color: #ffffff !important;
    font-size: 24px !important;
    font-weight: 800 !important;
    line-height: 1 !important;

    position: relative;
    z-index: 2;
}


/* نقطه طلایی تزئینی */
.number-icon::before {
    content: "";

    position: absolute;

    width: 12px;
    height: 12px;

    top: 7px;
    right: 7px;

    border-radius: 50%;

    background: #FFCE3A;

    opacity: 0.95;
}


/* هاور */
.number-icon:hover {
    transform: translateY(-4px);

    box-shadow:
        0 16px 35px rgba(0, 102, 96, 0.30) !important;
}

@media (max-width: 767px) {
    .number-icon {
        display: none !important;
    }
}
